// Service layer — generated by line-matcher. Do not add logic that belongs to another layer.
// External I/O only: one function per API endpoint.

async function request(method, url, body) {
  const res = await fetch(url, {
    method,
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) throw new Error(`${method} ${url} failed with ${res.status}`);
  return res.status === 204 ? null : res.json();
}

export const listContacts = () => request("GET", `/api/contacts`);
export const createContact = (data) => request("POST", `/api/contacts`, data);
export const updateContact = (id, data) =>
  request("PUT", `/api/contacts/${encodeURIComponent(id)}`, data);
export const deleteContact = (id) => request("DELETE", `/api/contacts/${encodeURIComponent(id)}`);
